do $$ declare rate constant numeric := 1.34; on_gbp boolean; begin select currency = 'GBP' into on_gbp from public.settings limit 1; if not coalesce(on_gbp, false) then raise notice 'Already off GBP - prices and bands left exactly as they are.'; return; end if; delete from public.fx_rates; insert into public.fx_rates (currency, rate_to_base, base_currency, source) values ('USD', 1, 'USD', 'fixed') on conflict (currency) do nothing; update public.pricing_rules set min_margin_minor = round(min_margin_minor * rate), paypal_fee_fixed_minor = 30, bank_fee_fixed_minor = round(bank_fee_fixed_minor * rate) where id = 1; update public.pricing_bands set min_cost_minor = round(min_cost_minor * rate), flat_minor = case when flat_minor is null then null else round(flat_minor * rate) end; update public.pricing_rounding set min_minor = round(min_minor * rate); update public.services set price_minor = round(price_minor * rate), agency_price_minor = case when agency_price_minor is null then null else round(agency_price_minor * rate) end; update public.website_niche_prices set price_minor = round(price_minor * rate), agency_price_minor = case when agency_price_minor is null then null else round(agency_price_minor * rate) end; delete from public.price_calculations; update public.settings set currency = 'USD'; raise notice 'Converted to USD at %. Refresh the rates, then recalculate.', rate; end; $$;
